import { GLOBAL_SEARCH_SHORTCUT_BINDING } from '../../services/search/search_open_service'
import { keyboardShortcutService } from '../../services/shortcuts/keyboard_shortcut_service'
import { AppMenu } from './menu/app_menu'
import { SearchControl } from './search/search_control'
import { StatusBar } from './status_bar'

interface MainWindowProps {
    auth: UseGithubAuthResult
    toolbarAction: ReactNode
}

/** Main window: owns the global layout and switches between desktop and mobile presentations. */
export function MainWindow(props: MainWindowProps) {
    const { auth, toolbarAction } = props
    const location = useAppLocation()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const [isMenuOpen, setIsMenuOpen] = useState(false)
    const project = useProjectReference()
    const isConfigOpen = location.pathname === '/config'
    const regexpAgent = useMemo(
        () => isSearchRegexpAgentAvailable() ? createSearchRegexpAgent() : undefined,
        [],
    )

    useEffect(() => keyboardShortcutService.register(GLOBAL_SEARCH_SHORTCUT_BINDING), [])

    const handleOpenMenu = useCallback(() => {
        setIsMenuOpen(true)
    }, [])

    const handleCloseMenu = useCallback(() => {
        setIsMenuOpen(false)
    }, [])

    const handleOpenConfig = useCallback(() => {
        navigateTo('/config')
    }, [])

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            <AppMenu
                accessToken={auth.accessToken}
                auth={auth}
                extraActions={toolbarAction}
                isGithubAuthenticated={auth.isAuthenticated}
                isMobile={isMobile}
                onOpenConfig={handleOpenConfig}
                onOpenMobileMenu={handleOpenMenu}
                search={<SearchControl isMobile={isMobile} regexpAgent={regexpAgent} />}
            />
            <ProjectWorkspace
                auth={auth}
                isMenuOpen={isMenuOpen}
                key={project ? `${project.id}:${project.branch}` : 'no-project'}
                onLeftPanelInteraction={handleCloseMenu}
            />
            {!isMobile ? <StatusBar /> : null}
            {isConfigOpen ? <ConfigPage hash={location.hash} /> : null}
        </Box>
    )
}

const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { resolveAppUrl } = require('./config');

const APPROVED_EXTERNAL_PROTOCOLS = new Set(['http:', 'https:']);
const PACKAGED_RENDERER_DIRECTORY = 'renderer';
const PACKAGED_RENDERER_ENTRY = 'index.html';

function resolveRendererTarget(isPackaged, appDirectory = __dirname, env = process.env) {
    if (isPackaged) {
        const filePath = path.join(appDirectory, PACKAGED_RENDERER_DIRECTORY, PACKAGED_RENDERER_ENTRY);

        return { filePath, trustedLocation: pathToFileURL(filePath).href, type: 'file' };
    }

    const url = resolveAppUrl(env);

    return { trustedLocation: url, type: 'url', url };
}

/** Directory holding the bundled React build, served over http by the remote-control server (F-045). */
function resolveRendererStaticDir(isPackaged, appDirectory = __dirname) {
    return isPackaged
        ? path.join(appDirectory, PACKAGED_RENDERER_DIRECTORY)
        : path.join(appDirectory, '..', 'app', 'dist');
}

function isTrustedRendererLocation(candidateUrl, trustedLocation) {
    try {
        const candidate = new URL(candidateUrl);
        const trusted = new URL(trustedLocation);
        candidate.hash = '';
        trusted.hash = '';

        return candidate.href === trusted.href;
    } catch {
        return false;
    }
}

function isApprovedExternalUrl(candidateUrl) {
    try {
        return APPROVED_EXTERNAL_PROTOCOLS.has(new URL(candidateUrl).protocol);
    } catch {
        return false;
    }
}

function registerNavigationGuards(webContents, trustedLocation, openExternal) {
    webContents.on('will-navigate', (event, url) => {
        if (isTrustedRendererLocation(url, trustedLocation)) return;

        event.preventDefault();
        if (isApprovedExternalUrl(url)) void openExternal(url);
    });
    webContents.setWindowOpenHandler(({ url }) => {
        if (isApprovedExternalUrl(url)) void openExternal(url);

        return { action: 'deny' };
    });
}

module.exports = {
    isApprovedExternalUrl,
    isTrustedRendererLocation,
    registerNavigationGuards,
    resolveRendererStaticDir,
    resolveRendererTarget,
};

